using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine();

var small = "The quick brown fox jumps over the lazy dog";
var large = string.Join(" ", Enumerable.Range(0, 10000).Select(i => $"word{i % 500}"));
var smallAnalyzer = new TextAnalyzer(small);
var largeAnalyzer = new TextAnalyzer(large);

const int WarmupIterations = 100;
const int Iterations = 10000;

// Warmup all methods
for (int i = 0; i < WarmupIterations; i++)
{
    smallAnalyzer.AverageWordLength();
    largeAnalyzer.AverageWordLength();
    smallAnalyzer.WordLengthHistogram();
    largeAnalyzer.WordLengthHistogram();
    smallAnalyzer.UniqueWordCount();
    largeAnalyzer.UniqueWordCount();
}

Console.WriteLine($"{"Method",-35} {"Mean (ns)",12} {"Iterations",12}");
Console.WriteLine(new string('-', 61));

Bench("AverageWordLength_Small", Iterations * 10, () => smallAnalyzer.AverageWordLength());
Bench("AverageWordLength_Large", Iterations, () => largeAnalyzer.AverageWordLength());
Bench("WordLengthHistogram_Small", Iterations * 10, () => smallAnalyzer.WordLengthHistogram());
Bench("WordLengthHistogram_Large", Iterations, () => largeAnalyzer.WordLengthHistogram());
Bench("UniqueWordCount_Small", Iterations * 10, () => smallAnalyzer.UniqueWordCount());
Bench("UniqueWordCount_Large", Iterations, () => largeAnalyzer.UniqueWordCount());

[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, int iterations, Func<object?> action)
{
    // Additional warmup per benchmark
    for (int i = 0; i < 100; i++) action();

    var sw = Stopwatch.StartNew();
    for (int i = 0; i < iterations; i++)
        action();
    sw.Stop();

    double meanNs = (double)sw.Elapsed.Ticks / iterations * 100.0;
    Console.WriteLine($"{name,-35} {meanNs,12:F1} {iterations,12}");
}

